SELECT z.zip_code, z.elevation
FROM zip_data AS z
WHERE z.type = 'Community Post Office' AND z.elevation > 6000;

SELECT 100.0 * SUM(CASE WHEN c.county = 'CORYELL' THEN z.households ELSE 0 END) / SUM(CASE WHEN z.state = (SELECT state FROM country WHERE county = 'CORYELL' LIMIT 1) THEN z.households ELSE 0 END) AS percentage
FROM zip_data AS z
JOIN country AS c ON c.zip_code = z.zip_code;

